/**
 * Maps Terraform validate -json diagnostics to TranslationFinding[].
 * Handles malformed JSON gracefully — never throws.
 *
 * @module validation/finding-mapper
 * @generated by code-generator (TASK-VAL-001)
 */

import type { TranslationFinding, FindingSeverity } from '@tla/shared';
import { createFinding } from '../engines/direct/attribute-transformer.js';

// ---------------------------------------------------------------------------
// Constants
// ---------------------------------------------------------------------------

/** Sentinel resourceId for all HCL-validation findings. */
export const HCL_VALIDATION_RESOURCE_ID = '__hcl_validation__';

// ---------------------------------------------------------------------------
// Terraform JSON types (subset of `terraform validate -json` output)
// ---------------------------------------------------------------------------

interface TerraformDiagnostic {
  readonly severity: string;
  readonly summary: string;
  readonly detail?: string;
}

interface TerraformValidateOutput {
  readonly valid: boolean;
  readonly error_count: number;
  readonly warning_count: number;
  readonly diagnostics: readonly TerraformDiagnostic[];
}

// ---------------------------------------------------------------------------
// Implementation
// ---------------------------------------------------------------------------

/**
 * Parses `terraform validate -json` stdout and converts each diagnostic
 * into a {@link TranslationFinding}.
 *
 * @param stdout - Raw stdout string from `terraform validate -json`.
 * @returns Array of findings; empty when validation passed cleanly.
 */
export function mapTerraformDiagnostics(stdout: string): TranslationFinding[] {
  let parsed: TerraformValidateOutput;
  try {
    parsed = JSON.parse(stdout) as TerraformValidateOutput;
  } catch {
    return [
      createFinding(
        HCL_VALIDATION_RESOURCE_ID,
        'warning',
        'HCL_VALIDATE_PARSE_ERROR',
        'Failed to parse terraform validate JSON output.',
        stdout.slice(0, 500),
      ),
    ];
  }

  const diagnostics = parsed.diagnostics;
  if (!Array.isArray(diagnostics) || diagnostics.length === 0) {
    return [];
  }

  return diagnostics.map((d) =>
    createFinding(
      HCL_VALIDATION_RESOURCE_ID,
      mapSeverity(d.severity),
      'HCL_VALIDATE_DIAGNOSTIC',
      d.summary || 'Unknown diagnostic',
      d.detail,
    ),
  );
}

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------

function mapSeverity(raw: string): FindingSeverity {
  switch (raw) {
    case 'error':
      return 'blocker';
    case 'warning':
      return 'warning';
    default:
      return 'info';
  }
}
